            result.add(permutation);
        }
    }
    return result;
}

public int findLargestSubstring(List<String> strings) {
    // Initialize the largest substring length to 0
    int largestSubstringLength = 0;

    // Iterate over each string in the list
    for (String string : strings) {
        // Get the length of the string
        int stringLength = string.length();

        // Check if the string is its own inverse
        if (string.equals(new StringBuilder(string).reverse().toString())) {
            // If the string is its own inverse, set the largest substring length to the string length
            largestSubstringLength = stringLength;
        } else {
            // Otherwise, iterate over each character in the string
            for (int i = 0; i < stringLength; i++) {
                // Get the character at the current index
                char character = string.charAt(i);

                // Check if the character is the last character in the string
                if (i == stringLength - 1) {
                    // If the character is the last character, set the largest substring length to the string length
                    largestSubstringLength = stringLength;
                } else {
                    // Otherwise, get the character at the next index
                    char nextCharacter = string.charAt(i + 1);

                    // Check if the character is the inverse of the next character
                    if (nextCharacter == Character.toLowerCase(character)) {
                        // If the character is the inverse of the next character, set the largest substring length to the string length
                        largestSubstringLength = stringLength;
                    }
                }
            }
        }
    }

    // Return the largest substring length
    return largestSubstringLength;
}

