public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Initialize a set to keep track of the visited nodes
    Set<Integer> visited = new HashSet<>();

    // Initialize a variable to keep track of the minimum time
    int minTime = 0;

    // Start at node 0 and add it to the queue
    queue.add(0);
    visited.add(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int current = queue.remove();

        // If the current node has an apple, add its neighbors to the queue and mark them as visited
        if (hasApple[current]) {
            for (int neighbor : graph.getNeighbors(current)) {
                if (!visited.contains(neighbor)) {
                    queue.add(neighbor);
                    visited.add(neighbor);
                }
            }
        }

        // Increment the minimum time
        minTime++;
    }

    // Return the minimum time
    return minTime;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (!s.isEmpty()) {
        // Pick the smallest character from s and append it to the result
        char smallest = s.charAt(0);
        result.append(smallest);
        s = s.substring(1);

        // Pick the smallest character from s which is greater than the last appended character to the result and append it
        int smallestIndex = s.indexOf(smallest);
        while (smallestIndex != -1) {
            char nextSmallest = s.charAt(smallestIndex + 1);
            if (nextSmallest > smallest) {
                result.append(nextSmallest);
                s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 2);
                break;
            }
            smallestIndex = s.indexOf(smallest, smallestIndex + 1);
        }

        // Pick the largest character from s and append it to the result
        char largest = s.charAt(s.length() - 1);
        result.append(largest);
        s = s.substring(0, s.length() - 1);

        // Pick the largest character from s which is smaller than the last appended character to the result and append it
        int largestIndex = s.lastIndexOf(largest);
        while (largestIndex != -1) {
            char nextLargest = s.charAt(largestIndex - 1);
            if (nextLargest < largest) {
                result.append(nextLargest);
                s = s.substring(0, largestIndex - 1) + s.substring(largestIndex);
                break;
            }
            largestIndex = s.lastIndexOf(largest, largestIndex - 1);
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of the input array
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Calculate the average of the input array
    int average = sum / nums.length;

    // Initialize two variables to keep track of the sum of the left and right arrays
    int leftSum = 0;
    int rightSum = 0;

    // Iterate over the input array
    for (int i = 0; i < nums.length; i++) {
        // If the current element is less than the average, add it to the left array
        if (nums[i] < average) {
            leftSum += nums[i];
        // Otherwise, add it to the right array
        } else {
            rightSum += nums[i];
        }
    }

    // Check if the sum of the left and right arrays is equal to the average
    return leftSum == rightSum && leftSum == average;
}

