public static int squarePermutations(int[] A) {
    // Initialize a set to store the unique permutations
    Set<String> permutations = new HashSet<>();

    // Sort the array in ascending order
    Arrays.sort(A);

    // Loop through each permutation of the array
    for (int i = 0; i < A.length; i++) {
        // Generate the permutation string
        String permutation = "";
        for (int j = 0; j < A.length; j++) {
            permutation += A[j];
        }

        // Check if the permutation is a square
        int sum = 0;
        for (int j = 0; j < A.length - 1; j++) {
            sum += A[j] * A[j + 1];
        }
        if (sum * sum == permutation.length()) {
            // If the permutation is a square, add it to the set
            permutations.add(permutation);
        }
    }

    // Return the number of unique permutations
    return permutations.size();
}

