    }

    int[] factors = new int[] { 2, 3, 5 };
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int factorIndex = 0;
    for (int i = 1; i < n; i++) {
        int minFactor = Integer.MAX_VALUE;
        for (int j = 0; j < factors.length; j++) {
            if (uglyNumbers[factorIndex] * factors[j] <= minFactor) {
                minFactor = uglyNumbers[factorIndex] * factors[j];
                factorIndex = j;
            }
        }
        uglyNumbers[i] = minFactor;
    }

    return uglyNumbers[n - 1];
}

